<?php
require_once __DIR__.'/includes/bootstrap.php';$user=require_login();$pageTitle='Dashboard · CineCast';require __DIR__.'/includes/header.php';?>
<main class="page-wrap"><div class="container"><div class="eyebrow dark">YOUR CINECAST SPACE</div><h1 class="page-title">Hello, <?=e($user['name'])?>.</h1><?php if($user['role']==='talent'):$s=db()->prepare("SELECT a.*,c.title,c.city,c.project_type FROM applications a JOIN casting_calls c ON c.id=a.casting_id WHERE a.talent_id=? ORDER BY a.created_at DESC");$s->execute([$user['id']]);$apps=$s->fetchAll();$p=db()->prepare('SELECT * FROM talent_profiles WHERE user_id=?');$p->execute([$user['id']]);$profile=$p->fetch();?><div class="section-heading"><div><h2>Your <em>journey.</em></h2><p class="muted">Keep your profile fresh and track your applications.</p></div><a class="btn btn-primary" href="<?=e(url('casting/index.php'))?>">Explore casting calls ↗</a></div><div class="content-card"><h3>Talent profile</h3><form method="post" action="<?=e(url('profile.php'))?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>CITY</label><input name="city" value="<?=e($profile['city']??'')?>"></div><div class="field"><label>AGE</label><input type="number" name="age" min="16" max="100" value="<?=e((string)($profile['age']??''))?>"></div><div class="field"><label>GENDER (OPTIONAL)</label><input name="gender" value="<?=e($profile['gender']??'')?>"></div><div class="field"><label>SKILLS</label><input name="skills" placeholder="Acting, dance, singing" value="<?=e($profile['skills']??'')?>"></div></div><div class="field"><label>ABOUT YOU</label><textarea name="bio"><?=e($profile['bio']??'')?></textarea></div><div class="field"><label>PORTFOLIO URL</label><input type="url" name="portfolio_url" value="<?=e($profile['portfolio_url']??'')?>"></div><button class="btn btn-dark form-submit">Save profile</button></form></div><h2 class="page-title" style="font-size:34px;margin-top:55px">Your applications</h2><?php if(!$apps):?><div class="empty-state">No applications yet. Your next role could be one click away.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Project</th><th>Location</th><th>Applied</th><th>Status</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><?=e($a['title'])?></td><td><?=e($a['city'])?></td><td><?=e(date('d M Y',strtotime($a['created_at'])))?></td><td class="status"><?=e($a['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php else:$s=db()->prepare('SELECT * FROM casting_calls WHERE user_id=? ORDER BY created_at DESC');$s->execute([$user['id']]);$jobs=$s->fetchAll();?><div class="section-heading"><div><h2>Your <em>productions.</em></h2><p class="muted">Publish roles and review incoming talent applications.</p></div><a class="btn btn-primary" href="<?=e(url('casting/create.php'))?>">+ Create casting call</a></div><?php if(!$jobs):?><div class="empty-state">You haven't posted a casting call yet. Create your first opportunity.</div><?php else:?><div class="cards-list"><?php foreach($jobs as $j):$n=db()->prepare('SELECT COUNT(*) FROM applications WHERE casting_id=?');$n->execute([$j['id']]);?><article class="job-card"><div class="job-meta"><span><?=e($j['project_type'])?></span><span><?=e($j['city'])?></span><span><?=e($j['status'])?></span></div><h3><?=e($j['title'])?></h3><p><?=e(mb_strimwidth($j['description'],0,130,'…'))?></p><a class="text-link" href="<?=e(url('casting/applicants.php?id='.$j['id']))?>">View <?=$n->fetchColumn()?> applicants ↗</a></article><?php endforeach;?></div><?php endif;?><?php endif;?></div></main><?php require __DIR__.'/includes/footer.php'; ?>